int InitQueue(SqQueue &Q)
{
    //构造一个空队列
    Q.front=Q.rear=0;
    return OK;
}

int QueueEmpty(SqQueue Q)
//队空时返回值为真,反之为假
{
    return(Q.front==Q.rear? TRUE:FALSE);
}

int QueueFull(SqQueue Q)
//队满时返回值为真,反之为假
{
    return((Q.rear+1)%MAXSIZE==Q.front?TRUE:FALSE);
}

int EnQueue(SqQueue &Q, Elemtype e)
{
    if(QueueFull(Q)) return ERROR;    //队满
    Q.rear=(Q.rear+1)%MAXSIZE;    //rear加1,队尾位置上移
    Q.data[Q.rear]=e;    //数据e存入当前队尾
    return OK;
}

int DeQueue(SqQueue &Q,Elemtype &e)
{
    if(QueueEmpty(Q)) return ERROR;    //队空
    Q.front=(Q.front+1)%MAXSIZE;    //front加1,队头位置上移
    e=Q.data[Q.front];
    return OK;
}

int QueueFront(SqQueue Q, Elemtype &e)
{
    if(QueueEmpty(Q)) return ERROR; // 队空
    e = Q.data[(Q.front + 1) % MAXSIZE]; // 取出队头数据
    return OK;
}
